// Des: Tests for pa-apiz-find: candidate URLs from shell pages
// Flo: HTML samples > apizFind > assert URLs and kinds
// I/O: inline HTML > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const find = @import("pa-apiz-find.zig");
const allo = std.testing.allocator;
fn findList(aren: std.mem.Allocator, norm: []const u8, page: []const u8) ![]find.Cand { return find.apizFind(aren, norm, page, &.{}); }
fn has(list: []const find.Cand, urlz: []const u8, kind: []const u8) bool { for (list) |item| if (std.mem.eql(u8, item.urlz, urlz) and std.mem.eql(u8, item.kind, kind)) return true; return false; }
test "link alternate json, relative and absolute" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/shop/list", "<link rel=\"alternate\" type=\"application/json\" href=\"/feed.json\"><link rel=\"alternate\" type=\"application/rss+xml\" href=\"/rss\"><link rel='alternate' type='application/feed+json' href='http://h.test/other.json'>", &.{}); try std.testing.expect(has(got, "http://h.test/feed.json", "link")); try std.testing.expect(has(got, "http://h.test/other.json", "link")); for (got) |item| try std.testing.expect(!std.mem.endsWith(u8, item.urlz, "/rss")); }
test "wordpress api.w.org link gives posts and pages" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/", "<link rel='https://api.w.org/' href='http://h.test/wp-json/' />", &.{}); try std.testing.expect(has(got, "http://h.test/wp-json/wp/v2/posts?per_page=10", "wpjs")); try std.testing.expect(has(got, "http://h.test/wp-json/wp/v2/pages?per_page=10", "wpjs")); }
test "next buildId builds the data URL, root is index" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const page = "<script id=\"__NEXT_DATA__\" type=\"application/json\">{\"buildId\":\"abc\",\"props\":{}}</script>"; const got = try findList(aren.allocator(), "http://h.test/", page); try std.testing.expect(has(got, "http://h.test/_next/data/abc/index.json", "next")); const two = try findList(aren.allocator(), "http://h.test/blog/post", page); try std.testing.expect(has(two, "http://h.test/_next/data/abc/blog/post.json", "next")); }
test "nuxt, sveltekit and openapi hints" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/docs", "<script id=\"__NUXT_DATA__\">[]</script> sveltekit swagger-ui", &.{}); try std.testing.expect(has(got, "http://h.test/docs/_payload.json", "nuxt")); try std.testing.expect(has(got, "http://h.test/docs/__data.json", "svel")); try std.testing.expect(has(got, "http://h.test/openapi.json", "oapi")); }
test "api strings in scripts, template strings skipped" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/x", "<script>fetch(\"/api/items?page=1\", &.{});fetch(`/api/${id}`);get('/api/user/me')</script>"); try std.testing.expect(has(got, "http://h.test/api/items?page=1", "scri")); try std.testing.expect(has(got, "http://h.test/api/user/me", "scri")); for (got) |item| try std.testing.expect(std.mem.indexOf(u8, item.urlz, "${") == null); }
test "iframe is a page candidate, other host dropped" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/a/b", "<iframe src=\"frame.html\"></iframe><iframe src=\"http://evil.test/x\"></iframe>", &.{}); try std.testing.expect(has(got, "http://h.test/a/frame.html", "ifrm")); for (got) |item| try std.testing.expect(std.mem.indexOf(u8, item.urlz, "evil") == null); for (got) |item| if (std.mem.eql(u8, item.kind, "ifrm")) try std.testing.expect(item.page); }
test "json twin, dedupe and cap" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://h.test/item/7", "<script>\"/api/a\" \"/api/a\"</script>", &.{}); try std.testing.expect(has(got, "http://h.test/item/7.json", "twin")); var cnt: usize = 0; for (got) |item| { if (std.mem.eql(u8, item.urlz, "http://h.test/api/a")) cnt += 1; } try std.testing.expectEqual(@as(usize, 1), cnt); var list: std.ArrayList(u8) = .empty; defer list.deinit(allo); var idx: usize = 0; while (idx < 60) : (idx += 1) { const part = try std.fmt.allocPrint(allo, "<link rel=\"alternate\" type=\"application/json\" href=\"/f{d}.json\">", .{idx}); defer allo.free(part); try list.appendSlice(allo, part); } const many = try findList(aren.allocator(), "http://h.test/", list.items); try std.testing.expect(many.len <= 32); }
test "page URL with a custom port keeps the port" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try findList(aren.allocator(), "http://127.0.0.1:8080/spa", "<script>fetch(\"/api/items\")</script>", &.{}); try std.testing.expect(has(got, "http://127.0.0.1:8080/api/items", "scri")); }
